node --test tests/visible.test.mjs && node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { buildOrder } from './src/order.mjs';
import { resolveName } from './src/registry.mjs';

const graph = {
  nodes: {
    app: { dependencies: ['storageAlias', 'core'] },
    storage: { dependencies: ['coreAlias'] },
    core: {},
    unused: { dependencies: ['missing'] },
  },
  aliases: { application: 'app', storageAlias: 'storage', coreAlias: 'core', appAlias: 'application' },
};
assert.equal(resolveName('appAlias', graph.nodes, graph.aliases), 'app');
assert.deepEqual(buildOrder(graph, ['application', 'appAlias']), ['core', 'storage', 'app']);
assert.throws(() => resolveName('x', {}, { x: 'y', y: 'x' }), /cycle/i);
assert.throws(() => resolveName('x', {}, { x: 'missing' }), /unknown/i);
assert.throws(() => buildOrder({ nodes: { a: { dependencies: ['bAlias'] }, b: { dependencies: ['aAlias'] } }, aliases: { aAlias: 'a', bAlias: 'b' } }, ['a']), /cycle/i);
assert.deepEqual(buildOrder({ nodes: { ok: {}, bad: { dependencies: ['missing'] } } }, ['ok']), ['ok']);
console.log('Additional alias and reachability checks passed');
EOF

